import java.math.BigDecimal;
import java.math.RoundingMode;

public class PriceParser {
    public static BigDecimal parse(String text) {
        if (text == null) {
            throw new IllegalArgumentException("no price");
        }
        String cleaned = text.replaceAll("[^0-9.]", "");
        if (!cleaned.matches(".*\\d.*")) {
            throw new IllegalArgumentException("no price");
        }
        return new BigDecimal(cleaned).setScale(2, RoundingMode.HALF_UP);
    }
}

coding.junit:
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.math.BigDecimal;
import org.junit.jupiter.api.Test;

class PriceParserTest {
    @Test
    void parsesPoundsWithSeparator() {
        assertEquals(new BigDecimal("1299.00"), PriceParser.parse("£1,299.00"));
    }

    @Test
    void padsToTwoDecimals() {
        assertEquals(new BigDecimal("5.50"), PriceParser.parse("$ 5.5"));
        assertEquals(new BigDecimal("12.00"), PriceParser.parse("12"));
    }

    @Test
    void rejectsTextWithoutDigits() {
        assertThrows(IllegalArgumentException.class, () -> PriceParser.parse("Free!"));
    }
}
